.stars{color:#f59e0b}.news-reviews-card{margin-top:14px;border:1px solid var(--line);border-radius:14px;background:#fff}.news-reviews-body{padding:17px}.rating-summary{display:flex;align-items:center;gap:12px;padding-bottom:14px;border-bottom:1px solid var(--line);margin-bottom:14px}.rating-big{font-size:36px;font-weight:900;color:var(--primary-dark)}.rating-summary .stars{font-size:18px}.rating-count{color:var(--muted);font-size:13px}.review-list{display:flex;flex-direction:column;gap:14px;margin-bottom:16px}.no-review{color:var(--muted);font-size:14px}.review-item{padding-bottom:14px;border-bottom:1px solid var(--line)}.review-item:last-child{border-bottom:0;padding-bottom:0}.review-head{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.review-head strong{color:var(--primary-dark);font-size:14px}.stars.small{font-size:12px}.review-date{color:var(--muted);font-size:12px}.review-comment{margin-top:6px;color:#485b66;font-size:14px;line-height:1.6}.review-form{padding-top:14px;border-top:1px solid var(--line)}.review-form h3{color:var(--primary-dark);font-size:15px;margin-bottom:10px}.star-select{font-size:22px;color:#d1d5db;margin-bottom:10px;cursor:pointer}.star-select i{margin-right:4px}.star-select i.fas{color:#f59e0b}.review-form textarea{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:8px;font-family:inherit;font-size:14px;resize:vertical}.btn-submit-review{margin-top:10px;height:40px;padding:0 18px;border:0;border-radius:8px;background:var(--primary);color:#fff;font-weight:bold;cursor:pointer}.review-note{color:var(--muted);font-size:13px;padding-top:14px;border-top:1px solid var(--line)}.review-note a{color:var(--primary);font-weight:bold}
